+    <title>Cat FAQ</title>
+    <style>
+      :root {
+        color-scheme: light;
+        --bg: #f6f8fc;
+        --panel: rgba(255, 255, 255, 0.82);
+        --panel-border: rgba(15, 23, 42, 0.08);
+        --text: #0f172a;
+        --muted: #475569;
+        --accent: #f97316;
+        --accent-soft: #fff1e8;
+        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
+        --radius: 22px;
+      }
+
+      * {
+        box-sizing: border-box;
+      }
+
+      body {
+        margin: 0;
+        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+        color: var(--text);
+        background:
+          radial-gradient(circle at top, rgba(249, 115, 22, 0.16), transparent 34%),
+          linear-gradient(180deg, #ffffff 0%, var(--bg) 100%);
+        min-height: 100vh;
+      }
+
+      .page {
+        width: min(960px, calc(100% - 32px));
+        margin: 0 auto;
+        padding: 56px 0 72px;
+      }
+
+      .hero {
+        padding: 28px 28px 18px;
+        border: 1px solid var(--panel-border);
+        border-radius: 30px;
+        background: var(--panel);
+        box-shadow: var(--shadow);
+        backdrop-filter: blur(18px);
+        margin-bottom: 22px;
+      }
+
+      .eyebrow {
+        display: inline-flex;
+        align-items: center;
+        gap: 8px;
+        padding: 8px 12px;
+        border-radius: 999px;
+        background: var(--accent-soft);
+        color: #9a3412;
+        font-size: 0.875rem;
+        font-weight: 700;
+        letter-spacing: 0.02em;
+      }
+
+      h1 {
+        margin: 16px 0 10px;
+        font-size: clamp(2.2rem, 5vw, 4rem);
+        line-height: 1.03;
+        letter-spacing: -0.04em;
+      }
+
+      .lead {
+        margin: 0;
+        max-width: 60ch;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.7;
+      }
+
+      .faq {
+        display: grid;
+        gap: 14px;
+      }
+
+      .example {
+        border: 1px solid var(--panel-border);
+        border-radius: var(--radius);
+        background: rgba(255, 255, 255, 0.88);
+        box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
+        overflow: hidden;
+      }
+
+      .question {
+        width: 100%;
+        appearance: none;
+        border: 0;
+        background: transparent;
+        color: inherit;
+        font: inherit;
+        text-align: left;
+        padding: 22px 24px;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 20px;
+        cursor: pointer;
+      }
+
+      .question:hover {
+        background: rgba(248, 250, 252, 0.9);
+      }
+
+      .question strong {
+        display: block;
+        font-size: 1.05rem;
+        line-height: 1.4;
+      }
+
+      .icon {
+        flex: 0 0 auto;
+        width: 36px;
+        height: 36px;
+        border-radius: 999px;
+        display: grid;
+        place-items: center;
+        background: var(--accent-soft);
+        color: var(--accent);
+        font-size: 1.3rem;
+        transition: transform 180ms ease;
+      }
+
+      .example.is-open .icon {
+        transform: rotate(45deg);
+      }
+
+      .details {
+        padding: 0 24px 22px;
+        color: var(--muted);
+        line-height: 1.75;
+        max-width: 72ch;
+      }
+
+      .details p {
+        margin: 0;
+      }
+
+      .details ul {
+        margin: 12px 0 0;
+        padding-left: 20px;
+      }
+
+      @media (max-width: 640px) {
+        .page {
+          width: min(100% - 20px, 960px);
+          padding: 20px 0 36px;
+        }
+
+        .hero {
+          padding: 22px 18px 16px;
+          border-radius: 24px;
+        }
+
+        .question {
+          padding: 18px 18px;
+        }
+
+        .details {
+          padding: 0 18px 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main class="page" id="app"></main>
+
+    <script>
+      const faqItems = [
+        {
+          question: "Why do cats purr?",
+          answer:
+            "Cats purr for several reasons: comfort, communication, self-soothing, and sometimes to ask for attention. A relaxed purr usually means your cat feels safe and content."
+        },
+        {
+          question: "How much sleep do cats need?",
+          answer:
+            "Most cats sleep 12 to 16 hours a day, and some kittens or senior cats sleep even more. Their energy comes in bursts, so naps are part of a normal cat routine."
+        },
+        {
+          question: "What should I feed my cat?",
+          answer:
+            "Cats need a complete diet with animal-based protein, water, and the right balance of nutrients. Choose food that matches your cat's age and health needs, and ask a vet before making major diet changes."
+        },
+        {
+          question: "Why do cats knead with their paws?",
+          answer:
+            "Kneading is a comforting behavior that starts in kittenhood. Adult cats often knead when they are relaxed, marking territory and showing trust."
+        },
+        {
+          question: "How can I make my cat happier at home?",
+          answer:
+            "Give your cat predictable routines, fresh water, clean litter boxes, scratching surfaces, vertical space, and daily play. Enrichment matters just as much as food and naps."
+        }
+      ];
+
+      function createFAQItem(item, index) {
+        return `
+          <div class="example" data-index="${index}">
+            <button class="question" type="button" aria-expanded="false" aria-controls="answer-${index}">
+              <strong>${item.question}</strong>
+              <span class="icon" aria-hidden="true">+</span>
+            </button>
+            <div class="details" id="answer-${index}" hidden>
+              <p>${item.answer}</p>
+            </div>
+          </div>
+        `;
+      }
+
+      function createFAQPage(items) {
+        return `
+          <section class="hero">
+            <span class="eyebrow">Cat FAQ</span>
+            <h1>Everything you wanted to know about cats.</h1>
+            <p class="lead">
+              A clean, friendly FAQ for curious cat people — with quick answers that expand when you need them.
+            </p>
+          </section>
+          <section class="faq" aria-label="Frequently asked questions">
+            ${items.map(createFAQItem).join("")}
+          </section>
+        `;
+      }
+
+      const app = document.getElementById("app");
+      app.innerHTML = createFAQPage(faqItems);
+
+      app.addEventListener("click", (event) => {
+        const button = event.target.closest(".question");
+        if (!button) return;
+
+        const example = button.closest(".example");
+        const details = example.querySelector(".details");
+        const expanded = button.getAttribute("aria-expanded") === "true";
+
+        button.setAttribute("aria-expanded", String(!expanded));
+        details.hidden = expanded;
+        example.classList.toggle("is-open", !expanded);
+      });
+    </script>
+  </body>
+</html>
*** End Patch
