        border-radius: 30px;
        background: var(--panel);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
        margin-bottom: 22px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: #9a3412;
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 16px 0 10px;
        font-size: clamp(2.2rem, 5vw, 4rem);
        line-height: 1.03;
        letter-spacing: -0.04em;
      }

      .lead {
        margin: 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq {
        display: grid;
        gap: 14px;
      }

      .example {
        border: 1px solid var(--panel-border);
        border-radius: var(--radius);
        background: rgba(255, 255, 255, 0.88);
        box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
        overflow: hidden;
      }

      .question {
        width: 100%;
        appearance: none;
        border: 0;
        background: transparent;
        color: inherit;
        font: inherit;
        text-align: left;
        padding: 22px 24px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 20px;
        cursor: pointer;
      }

      .question:hover {
        background: rgba(248, 250, 252, 0.9);
      }

      .question strong {
        display: block;
        font-size: 1.05rem;
        line-height: 1.4;
      }

      .icon {
        flex: 0 0 auto;
        width: 36px;
        height: 36px;
        border-radius: 999px;
        display: grid;
        place-items: center;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 1.3rem;
        transition: transform 180ms ease;
      }

      .example.is-open .icon {
        transform: rotate(45deg);
      }

      .details {
        padding: 0 24px 22px;
        color: var(--muted);
        line-height: 1.75;
        max-width: 72ch;
      }

      .details p {
        margin: 0;
      }

      .details ul {
        margin: 12px 0 0;
        padding-left: 20px;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 960px);
          padding: 20px 0 36px;
        }

        .hero {
          padding: 22px 18px 16px;
          border-radius: 24px;
        }

        .question {
          padding: 18px 18px;
        }

        .details {
          padding: 0 18px 18px;
        }
      }
